contracts/AgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AgentRegistry
 * @notice Registers AI agents on SynapseMesh. Agents stake OG tokens to participate,
 *         earn reputation by completing tasks, and can be slashed for poor work.
 * @dev Deployed first. Address passed into AgentRegistry constructor.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _meshEscrow     : address of MeshEscrow (deploy MeshEscrow first, paste address here)
 *   _teeVerifier    : address of TEEVerifierBridge (deploy after, then call setTeeVerifier)
 *   _treasury       : wallet that receives slashed stake (use TREASURY_ADDRESS from .env)
 *
 * POST-DEPLOY:
 *   Call setTeeVerifier(teeVerifierAddress) after TEEVerifierBridge is deployed.
 */
contract AgentRegistry {

    // ─────────────────────────────────────────────────────────────
    //  Data structures
    // ─────────────────────────────────────────────────────────────

    struct Agent {
        address owner;
        bytes32 agentId;          // keccak256 of agent's 0G Agent ID string
        uint256 stakedAmount;     // OG tokens locked (wei units)
        uint256 reputation;       // 0–1000 scale, starts at 500
        uint256 tasksCompleted;
        uint256 totalEarned;      // cumulative OG earned (informational)
        bool    slashed;          // ever slashed flag
        bool    active;           // false = withdrawn / deregistered
    }

    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    mapping(address => Agent)  public agents;
    mapping(address => bool)   public registered;
    mapping(bytes32 => address) public agentIdToOwner; // reverse lookup

    uint256 public MIN_STAKE   = 0.05 ether;  // governance can update
    address public meshEscrow;
    address public teeVerifier;
    address public treasury;
    address public owner;

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event AgentRegistered(address indexed agent, bytes32 agentId, uint256 stake);
    event ReputationUpdated(address indexed agent, uint256 newScore);
    event AgentSlashed(address indexed agent, uint256 penalty);
    event AgentDeregistered(address indexed agent, uint256 stakeReturned);
    event EarningsRecorded(address indexed agent, uint256 amount, uint256 totalEarned);
    event MinStakeUpdated(uint256 newMin);
    event TeeVerifierSet(address teeVerifier);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyAuthorized() {
        require(
            msg.sender == meshEscrow || msg.sender == teeVerifier,
            "AgentRegistry: unauthorized caller"
        );
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "AgentRegistry: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _meshEscrow,
        address _treasury
    ) {
        require(_meshEscrow != address(0), "zero escrow");
        require(_treasury   != address(0), "zero treasury");
        meshEscrow = _meshEscrow;
        treasury   = _treasury;
        owner      = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    /// @notice Call this after TEEVerifierBridge is deployed
    function setTeeVerifier(address _teeVerifier) external onlyOwner {
        require(_teeVerifier != address(0), "zero verifier");
        teeVerifier = _teeVerifier;
        emit TeeVerifierSet(_teeVerifier);
    }

    function setMinStake(uint256 _min) external onlyOwner {
        require(_min > 0, "AgentRegistry: zero min");
        MIN_STAKE = _min;
        emit MinStakeUpdated(_min);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "AgentRegistry: zero owner");
        address previous = owner;
        owner = newOwner;
        emit OwnershipTransferred(previous, newOwner);
    }

    // ─────────────────────────────────────────────────────────────
    //  Registration
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Register as an agent. Must send >= MIN_STAKE OG.
     * @param _agentId  keccak256 hash of your 0G Agent ID string
     */
    function register(bytes32 _agentId) external payable {
        require(!registered[msg.sender],          "AgentRegistry: already registered");
        require(msg.value >= MIN_STAKE,            "AgentRegistry: stake too low");
        require(agentIdToOwner[_agentId] == address(0), "AgentRegistry: agentId taken");

        agents[msg.sender] = Agent({
            owner:          msg.sender,
            agentId:        _agentId,
            stakedAmount:   msg.value,
            reputation:     500,
            tasksCompleted: 0,
            totalEarned:    0,
            slashed:        false,
            active:         true
        });

        registered[msg.sender]       = true;
        agentIdToOwner[_agentId]     = msg.sender;

        emit AgentRegistered(msg.sender, _agentId, msg.value);
    }

    /**
     * @notice Deregister and withdraw stake. Only callable when not assigned to any task.
     */
    function deregister() external {
        require(registered[msg.sender],         "AgentRegistry: not registered");
        require(agents[msg.sender].active,      "AgentRegistry: already inactive");

        Agent storage a = agents[msg.sender];
        uint256 refund  = a.stakedAmount;
        a.stakedAmount  = 0;
        a.active        = false;

        delete agentIdToOwner[a.agentId];
        registered[msg.sender] = false;

        _sendValue(msg.sender, refund);
        emit AgentDeregistered(msg.sender, refund);
    }

    // ─────────────────────────────────────────────────────────────
    //  Reputation & slashing — called by TEEVerifierBridge
    // ─────────────────────────────────────────────────────────────

    function incrementReputation(address _agent, uint8 _score) external onlyAuthorized {
        Agent storage a = agents[_agent];
        require(registered[_agent] && a.active, "AgentRegistry: agent not active");
        uint256 boost = _score > 85 ? 10 : (_score > 70 ? 5 : 2);
        a.reputation = (a.reputation + boost > 1000) ? 1000 : a.reputation + boost;
        a.tasksCompleted++;
        emit ReputationUpdated(_agent, a.reputation);
    }

    function slash(address _agent) external onlyAuthorized {
        Agent storage a = agents[_agent];
        require(registered[_agent] && a.active, "AgentRegistry: agent not active");

        uint256 penalty = a.stakedAmount / 10; // 10% slash
        a.stakedAmount -= penalty;
        a.reputation    = a.reputation > 50 ? a.reputation - 50 : 0;
        a.slashed       = true;

        _sendValue(treasury, penalty);
        emit AgentSlashed(_agent, penalty);
    }

    function recordEarnings(address _agent, uint256 amount) external onlyAuthorized {
        Agent storage a = agents[_agent];
        require(registered[_agent] && a.active, "AgentRegistry: agent not active");
        a.totalEarned += amount;
        emit EarningsRecorded(_agent, amount, a.totalEarned);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getReputation(address _agent) external view returns (uint256) {
        return agents[_agent].reputation;
    }

    function getAgent(address _agent) external view returns (Agent memory) {
        return agents[_agent];
    }

    function isRegistered(address _agent) external view returns (bool) {
        return registered[_agent];
    }

    function _sendValue(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = payable(to).call{value: amount}("");
        require(ok, "AgentRegistry: transfer failed");
    }
}

contracts/BidEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IAgentRegistry {
function getReputation(address agent) external view returns (uint256);
function isRegistered(address agent) external view returns (bool);
}

interface IDAGRegistry {
function markNodeAssigned(bytes32 taskId, address agent) external;
function markNodeFailed(bytes32 taskId) external;
function getNodeStatus(bytes32 taskId) external view returns (uint8);
}

/**
 * @title BidEngine
 * @notice Reputation-weighted auction for DAG task nodes.
 *         Agents submit bids; the AUCTIONEER_ADDRESS calls awardBid.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _agentRegistry : address of AgentRegistry
 *   _dagRegistry   : address of TaskDAGRegistry
 *   _auctioneer    : AUCTIONEER_ADDRESS from .env — TEE-managed key in production
 *
 * DEPLOY ORDER: After AgentRegistry and TaskDAGRegistry.
 */
contract BidEngine {

    // ─────────────────────────────────────────────────────────────
    //  Data structures
    // ─────────────────────────────────────────────────────────────

    struct Bid {
        address agent;
        uint256 price;       // OG wei the agent accepts
        uint256 eta;         // estimated blocks to complete
        uint256 reputation;  // snapshot at bid time
        uint256 submittedAt;
    }

    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    mapping(bytes32 => Bid[])   public bids;           // taskId => bids
    mapping(bytes32 => bool)    public awarded;         // taskId => already awarded
    mapping(bytes32 => address) public winner;          // taskId => winning agent

    address public agentRegistry;
    address public dagRegistry;
    address public auctioneer;   // AUCTIONEER_ADDRESS — only address that can call awardBid
    address public owner;

    uint256 public BID_WINDOW = 20; // blocks agents have to bid after node opens

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event BidSubmitted(bytes32 indexed taskId, address agent, uint256 price, uint256 eta);
    event BidAwarded(bytes32 indexed taskId, address winner, uint256 price);
    event NodeFailed(bytes32 indexed taskId, string reason);

    // ─────────────────────────────────────────────────────────────
    //  Interfaces
    // ─────────────────────────────────────────────────────────────





    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyAuctioneer() {
        require(msg.sender == auctioneer, "BidEngine: only auctioneer");
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "BidEngine: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _agentRegistry,
        address _dagRegistry,
        address _auctioneer
    ) {
        require(_agentRegistry != address(0), "zero agentRegistry");
        require(_dagRegistry   != address(0), "zero dagRegistry");
        require(_auctioneer    != address(0), "zero auctioneer");

        agentRegistry = _agentRegistry;
        dagRegistry   = _dagRegistry;
        auctioneer    = _auctioneer;
        owner         = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Bidding
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Submit a bid for a task node.
     * @param taskId  bytes32 task identifier from TaskDAGRegistry
     * @param price   OG wei the agent will accept for this task
     * @param eta     how many blocks the agent estimates to complete
     */
    function submitBid(
        bytes32 taskId,
        uint256 price,
        uint256 eta
    ) external {
        IAgentRegistry reg = IAgentRegistry(agentRegistry);
        require(reg.isRegistered(msg.sender), "BidEngine: agent not registered");
        require(!awarded[taskId],             "BidEngine: already awarded");
        require(IDAGRegistry(dagRegistry).getNodeStatus(taskId) == 1, "BidEngine: node not biddable");
        require(price > 0,                    "BidEngine: zero price");
        require(eta > 0,                      "BidEngine: zero eta");
        require(!_hasBid(taskId, msg.sender), "BidEngine: duplicate bid");

        uint256 rep = reg.getReputation(msg.sender);

        bids[taskId].push(Bid({
            agent:       msg.sender,
            price:       price,
            eta:         eta,
            reputation:  rep,
            submittedAt: block.number
        }));

        emit BidSubmitted(taskId, msg.sender, price, eta);
    }

    /**
     * @notice Award a bid to the selected agent. Called by the auctioneer
     *         (TEE-managed key). The auctioneer runs the scoring off-chain
     *         and submits the winner address.
     *
     *         Scoring formula (off-chain): score = (rep * 0.5) + (1/price * 0.3) + (1/eta * 0.2)
     *
     * @param taskId        bytes32 task identifier
     * @param winnerAgent   address of winning agent
     */
    function awardBid(bytes32 taskId, address winnerAgent) external onlyAuctioneer {
        require(!awarded[taskId], "BidEngine: already awarded");
        require(IDAGRegistry(dagRegistry).getNodeStatus(taskId) == 1, "BidEngine: node not biddable");
        require(_hasBid(taskId, winnerAgent), "BidEngine: winner has no bid");

        awarded[taskId]  = true;
        winner[taskId]   = winnerAgent;

        IDAGRegistry(dagRegistry).markNodeAssigned(taskId, winnerAgent);

        // find the winning bid price for event
        uint256 price;
        Bid[] memory nodeBids = bids[taskId];
        for (uint256 i = 0; i < nodeBids.length; i++) {
            if (nodeBids[i].agent == winnerAgent) {
                price = nodeBids[i].price;
                break;
            }
        }

        emit BidAwarded(taskId, winnerAgent, price);
    }

    /**
     * @notice Mark a node as failed (no valid bids / timeout).
     *         Called by auctioneer.
     */
    function failNode(bytes32 taskId, string calldata reason) external onlyAuctioneer {
        require(!awarded[taskId], "BidEngine: already awarded");
        require(IDAGRegistry(dagRegistry).getNodeStatus(taskId) == 1, "BidEngine: node not biddable");
        awarded[taskId] = true;
        IDAGRegistry(dagRegistry).markNodeFailed(taskId);
        emit NodeFailed(taskId, reason);
    }

    // ─────────────────────────────────────────────────────────────
    //  Internal
    // ─────────────────────────────────────────────────────────────

    function _hasBid(bytes32 taskId, address agent) internal view returns (bool) {
        Bid[] memory nodeBids = bids[taskId];
        for (uint256 i = 0; i < nodeBids.length; i++) {
            if (nodeBids[i].agent == agent) return true;
        }
        return false;
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getBids(bytes32 taskId) external view returns (Bid[] memory) {
        return bids[taskId];
    }

    function getBidCount(bytes32 taskId) external view returns (uint256) {
        return bids[taskId].length;
    }

    function getWinner(bytes32 taskId) external view returns (address) {
        return winner[taskId];
    }
}

contracts/EvolutionClock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IGenOps {
function runEpoch(uint256 generation) external;
}

/**
 * @title EvolutionClock
 * @notice Epoch timer for the Evolution Lab. Anyone can call triggerEpoch()
 *         once epochLength blocks have passed. Calls GenOps.runEpoch() which
 *         backend listens to for running selection + crossover + mutation.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _genOps      : address of GenOps
 *   _epochLength : number of blocks per generation (e.g. 100 blocks ≈ 100 seconds on 0G)
 *
 * DEPLOY ORDER: After GenOps.
 */
contract EvolutionClock {

    // ─────────────────────────────────────────────────────────────
    //  Interface
    // ─────────────────────────────────────────────────────────────



    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    address public genOps;
    address public owner;

    uint256 public epochLength;       // blocks per generation
    uint256 public lastEpochBlock;    // block when last epoch was triggered
    uint256 public currentGeneration; // increments each epoch

    bool public paused;

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event EpochTriggered(uint256 indexed generation, uint256 blockNumber, address triggeredBy);
    event EpochLengthUpdated(uint256 newLength);
    event Paused(bool isPaused);
    event GenOpsUpdated(address newGenOps);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "EvolutionClock: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(address _genOps, uint256 _epochLength) {
        require(_genOps != address(0), "zero genOps");
        require(_epochLength > 0,      "zero epochLength");
        genOps        = _genOps;
        epochLength   = _epochLength;
        lastEpochBlock = block.number;
        owner         = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function setEpochLength(uint256 _newLength) external onlyOwner {
        require(_newLength > 0, "zero length");
        epochLength = _newLength;
        emit EpochLengthUpdated(_newLength);
    }

    function setGenOps(address _genOps) external onlyOwner {
        require(_genOps != address(0), "zero genOps");
        genOps = _genOps;
        emit GenOpsUpdated(_genOps);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "EvolutionClock: zero owner");
        address previous = owner;
        owner = newOwner;
        emit OwnershipTransferred(previous, newOwner);
    }

    // ─────────────────────────────────────────────────────────────
    //  Epoch trigger — callable by anyone
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Trigger the next evolution epoch.
     *         Anyone can call this once epochLength blocks have passed.
     *         The call forwards to GenOps.runEpoch() which emits an event
     *         the backend listens to for running genetic operations off-chain.
     */
    function triggerEpoch() external {
        require(!paused, "EvolutionClock: paused");
        require(
            block.number >= lastEpochBlock + epochLength,
            "EvolutionClock: epoch not over yet"
        );

        lastEpochBlock = block.number;
        currentGeneration++;

        emit EpochTriggered(currentGeneration, block.number, msg.sender);

        // Notify GenOps — backend listens to SelectionRun event from GenOps
        IGenOps(genOps).runEpoch(currentGeneration);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function blocksUntilNextEpoch() external view returns (uint256) {
        uint256 next = lastEpochBlock + epochLength;
        return block.number >= next ? 0 : next - block.number;
    }

    function isEpochReady() external view returns (bool) {
        return !paused && block.number >= lastEpochBlock + epochLength;
    }

    function getGeneration() external view returns (uint256) {
        return currentGeneration;
    }
}

contracts/FitnessOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IModelGenome {
function submitFitness(uint256 genomeId, uint8 score) external;
function isActive(uint256 genomeId) external view returns (bool);
}

/**
 * @title FitnessOracle
 * @notice Receives TEE-signed fitness scores for genome NFTs.
 *         Anyone can request evaluation; backend listens to EvaluationRequested,
 *         runs inference on 0G Compute TEE, and submits the signed result back.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _genome  : address(0) initially — set via setGenome() after ModelGenome deploys
 *   _signer  : TEE_SIGNER_ADDRESS from .env
 *   _mrEnclave : TEE_MR_ENCLAVE from .env
 *
 * DEPLOY ORDER: Before ModelGenome.
 *               After ModelGenome deploys, call setGenome(modelGenomeAddress).
 */
contract FitnessOracle {

    // ─────────────────────────────────────────────────────────────
    //  Interface
    // ─────────────────────────────────────────────────────────────



    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    address public genome;
    address public trustedSigner;   // TEE_SIGNER_ADDRESS
    bytes32 public trustedEnclave;  // TEE_MR_ENCLAVE
    address public owner;

    mapping(uint256 => uint256) public lastEvalBlock;    // genomeId => last eval block
    mapping(uint256 => uint8)   public lastFitnessScore; // genomeId => last score

    uint256 public MIN_EVAL_INTERVAL = 100; // blocks between evaluations
    uint256 private constant SECP256K1N_HALF =
        0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0;

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event EvaluationRequested(uint256 indexed genomeId, uint256 blockNumber);
    event FitnessSubmitted(uint256 indexed genomeId, uint8 score, bytes32 benchmarkHash);
    event GenomeSet(address genome);
    event SignerUpdated(address newSigner);
    event EnclaveUpdated(bytes32 newEnclave);
    event EvalIntervalUpdated(uint256 newInterval);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "FitnessOracle: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _signer,
        bytes32 _mrEnclave
    ) {
        require(_signer != address(0), "zero signer");
        trustedSigner  = _signer;
        trustedEnclave = _mrEnclave;
        owner          = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function setGenome(address _genome) external onlyOwner {
        require(_genome != address(0), "zero genome");
        genome = _genome;
        emit GenomeSet(_genome);
    }

    function updateSigner(address _signer) external onlyOwner {
        require(_signer != address(0), "zero signer");
        trustedSigner = _signer;
        emit SignerUpdated(_signer);
    }

    function updateEnclave(bytes32 _enclave) external onlyOwner {
        trustedEnclave = _enclave;
        emit EnclaveUpdated(_enclave);
    }

    function setMinEvalInterval(uint256 _interval) external onlyOwner {
        MIN_EVAL_INTERVAL = _interval;
        emit EvalIntervalUpdated(_interval);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "FitnessOracle: zero owner");
        address previous = owner;
        owner = newOwner;
        emit OwnershipTransferred(previous, newOwner);
    }

    // ─────────────────────────────────────────────────────────────
    //  Evaluation flow
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Request a fitness evaluation for a genome.
     *         Anyone can call this. Backend listens to EvaluationRequested,
     *         runs benchmarks on 0G Compute TEE, then calls submitFitness().
     *
     * @param genomeId  Token ID of the genome to evaluate
     */
    function requestEvaluation(uint256 genomeId) external {
        require(genome != address(0),               "FitnessOracle: genome not set");
        require(IModelGenome(genome).isActive(genomeId), "FitnessOracle: genome not active");
        require(
            lastEvalBlock[genomeId] == 0 ||
                block.number >= lastEvalBlock[genomeId] + MIN_EVAL_INTERVAL,
            "FitnessOracle: too soon since last eval"
        );

        lastEvalBlock[genomeId] = block.number;
        emit EvaluationRequested(genomeId, block.number);
    }

    /**
     * @notice Submit a TEE-signed fitness score.
     *         Called by the backend after receiving TEE result from 0G Compute.
     *
     * @param genomeId      Token ID
     * @param score         0–100 fitness score
     * @param benchmarkHash keccak256 of benchmark prompts used in evaluation
     * @param teeSignature  ECDSA sig from TEE node
     *                      Message: keccak256(chainId, oracle, genomeId, score, benchmarkHash, mrEnclave)
     */
    function submitFitness(
        uint256        genomeId,
        uint8          score,
        bytes32        benchmarkHash,
        bytes calldata teeSignature
    ) external {
        require(genome != address(0), "FitnessOracle: genome not set");
        require(score <= 100, "FitnessOracle: score > 100");

        // Verify TEE signature includes mrEnclave for enclave binding
        bytes32 msgHash = keccak256(
            abi.encodePacked(
                block.chainid,
                address(this),
                genomeId,
                score,
                benchmarkHash,
                trustedEnclave
            )
        );
        bytes32 ethHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", msgHash)
        );

        address recovered = _recover(ethHash, teeSignature);
        require(recovered == trustedSigner, "FitnessOracle: invalid TEE signature");

        lastFitnessScore[genomeId] = score;

        IModelGenome(genome).submitFitness(genomeId, score);
        emit FitnessSubmitted(genomeId, score, benchmarkHash);
    }

    // ─────────────────────────────────────────────────────────────
    //  Internal — ECDSA recovery
    // ─────────────────────────────────────────────────────────────

    function _recover(bytes32 h, bytes calldata sig) internal pure returns (address) {
        require(sig.length == 65, "FitnessOracle: bad sig length");
        bytes32 r;
        bytes32 s;
        uint8   v;
        assembly {
            r := calldataload(sig.offset)
            s := calldataload(add(sig.offset, 32))
            v := byte(0, calldataload(add(sig.offset, 64)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "FitnessOracle: bad v");
        require(uint256(s) <= SECP256K1N_HALF, "FitnessOracle: bad s");
        return ecrecover(h, v, r, s);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getLastScore(uint256 genomeId) external view returns (uint8) {
        return lastFitnessScore[genomeId];
    }

    function blocksUntilNextEval(uint256 genomeId) external view returns (uint256) {
        uint256 next = lastEvalBlock[genomeId] + MIN_EVAL_INTERVAL;
        return block.number >= next ? 0 : next - block.number;
    }
}

contracts/GenomeDAO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IModelGenome {
function getSpeciesPopulation(bytes32 speciesId) external view returns (uint256[] memory);
function isActive(uint256 genomeId) external view returns (bool);
function ownerOf(uint256 tokenId) external view returns (address);
function setThresholds(uint8 extinction, uint8 deployment) external;
function EXTINCTION_THRESHOLD() external view returns (uint8);
function DEPLOYMENT_THRESHOLD() external view returns (uint8);
}

interface IEvolutionClock {
function setEpochLength(uint256 newLen) external;
}

interface IGenOps {
function setMutationRate(uint256 rate) external;
}

interface IAgentRegistry {
function setMinStake(uint256 minStake) external;
}

/**
 * @title GenomeDAO
 * @notice Governance contract. Genome NFT holders vote on evolution parameters:
 *         mutation rate, epoch length, extinction threshold, deployment threshold.
 *         Voting power = number of ACTIVE genomes owned.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _genome      : address of ModelGenome
 *   _evoClock    : address of EvolutionClock
 *   _genOps      : address of GenOps
 *   _votingPeriod: blocks proposals stay open (e.g. 1000 blocks ≈ ~17 min on 0G)
 *   _quorum      : minimum votes to pass a proposal (e.g. 3)
 *
 * DEPLOY ORDER: Last — after all other contracts.
 */
contract GenomeDAO {

    // ─────────────────────────────────────────────────────────────
    //  Enums
    // ─────────────────────────────────────────────────────────────

    enum ProposalType {
        SET_MUTATION_RATE,        // GenOps.setMutationRate()
        SET_EPOCH_LENGTH,         // EvolutionClock.setEpochLength()
        SET_EXTINCTION_THRESHOLD, // ModelGenome.setThresholds()
        SET_DEPLOYMENT_THRESHOLD, // ModelGenome.setThresholds()
        SET_MIN_STAKE,            // AgentRegistry.setMinStake()
        CUSTOM                    // arbitrary encoded call — owner only
    }

    enum ProposalStatus { ACTIVE, PASSED, FAILED, EXECUTED }

    // ─────────────────────────────────────────────────────────────
    //  Data structures
    // ─────────────────────────────────────────────────────────────

    struct Proposal {
        uint256      id;
        address      proposer;
        ProposalType pType;
        uint256      value;        // new value to set
        string       description;
        uint256      forVotes;
        uint256      againstVotes;
        uint256      startBlock;
        uint256      endBlock;
        ProposalStatus status;
        bool         executed;
    }

    // ─────────────────────────────────────────────────────────────
    //  Interfaces
    // ─────────────────────────────────────────────────────────────







    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    mapping(uint256 => Proposal)                  public proposals;
    mapping(uint256 => mapping(address => bool))  public hasVoted;   // proposalId => voter => voted

    address public genome;
    address public evoClock;
    address public genOps;
    address public agentRegistry;
    address public owner;

    uint256 public proposalCount;
    uint256 public votingPeriod;  // blocks
    uint256 public quorum;        // minimum for-votes to pass

    // Species IDs for vote weight calculation
    bytes32[] public registeredSpecies;

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event ProposalCreated(uint256 indexed id, address proposer, ProposalType pType, uint256 value);
    event VoteCast(uint256 indexed proposalId, address voter, bool support, uint256 weight);
    event ProposalExecuted(uint256 indexed id, bool passed);
    event QuorumUpdated(uint256 newQuorum);
    event VotingPeriodUpdated(uint256 newPeriod);
    event AgentRegistryUpdated(address agentRegistry);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "GenomeDAO: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _genome,
        address _evoClock,
        address _genOps,
        address _agentRegistry,
        uint256 _votingPeriod,
        uint256 _quorum
    ) {
        require(_genome   != address(0), "zero genome");
        require(_evoClock != address(0), "zero evoClock");
        require(_genOps   != address(0), "zero genOps");
        require(_votingPeriod > 0,       "zero voting period");
        require(_quorum > 0,             "zero quorum");

        genome        = _genome;
        evoClock      = _evoClock;
        genOps        = _genOps;
        agentRegistry = _agentRegistry;
        votingPeriod  = _votingPeriod;
        quorum        = _quorum;
        owner         = msg.sender;

        // Register default species IDs
        registeredSpecies.push(keccak256("writing"));
        registeredSpecies.push(keccak256("code"));
        registeredSpecies.push(keccak256("reasoning"));
        registeredSpecies.push(keccak256("creative"));
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function setQuorum(uint256 _quorum) external onlyOwner {
        require(_quorum > 0, "GenomeDAO: zero quorum");
        quorum = _quorum;
        emit QuorumUpdated(_quorum);
    }

    function setVotingPeriod(uint256 _period) external onlyOwner {
        require(_period > 0, "GenomeDAO: zero period");
        votingPeriod = _period;
        emit VotingPeriodUpdated(_period);
    }

    function addSpecies(bytes32 speciesId) external onlyOwner {
        registeredSpecies.push(speciesId);
    }

    function setAgentRegistry(address _agentRegistry) external onlyOwner {
        require(_agentRegistry != address(0), "GenomeDAO: zero agentRegistry");
        agentRegistry = _agentRegistry;
        emit AgentRegistryUpdated(_agentRegistry);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "GenomeDAO: zero owner");
        address previous = owner;
        owner = newOwner;
        emit OwnershipTransferred(previous, newOwner);
    }

    // ─────────────────────────────────────────────────────────────
    //  Governance
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Create a governance proposal.
     *         Proposer must own at least 1 active genome NFT.
     *
     * @param pType       Type of parameter to change
     * @param value       New value to set
     * @param description Human-readable description of the proposal
     */
    function propose(
        ProposalType pType,
        uint256      value,
        string calldata description
    ) external returns (uint256) {
        require(_votingPower(msg.sender) > 0, "GenomeDAO: no voting power");
        _validateProposal(pType, value);

        uint256 id = ++proposalCount;

        proposals[id] = Proposal({
            id:           id,
            proposer:     msg.sender,
            pType:        pType,
            value:        value,
            description:  description,
            forVotes:     0,
            againstVotes: 0,
            startBlock:   block.number,
            endBlock:     block.number + votingPeriod,
            status:       ProposalStatus.ACTIVE,
            executed:     false
        });

        emit ProposalCreated(id, msg.sender, pType, value);
        return id;
    }

    /**
     * @notice Cast a vote on a proposal.
     *         Voting power = number of active genome NFTs owned by caller.
     *
     * @param proposalId  Proposal to vote on
     * @param support     true = for, false = against
     */
    function vote(uint256 proposalId, bool support) external {
        Proposal storage p = proposals[proposalId];
        require(p.status == ProposalStatus.ACTIVE, "GenomeDAO: not active");
        require(block.number <= p.endBlock,         "GenomeDAO: voting ended");
        require(!hasVoted[proposalId][msg.sender],  "GenomeDAO: already voted");

        uint256 weight = _votingPower(msg.sender);
        require(weight > 0, "GenomeDAO: no voting power");

        hasVoted[proposalId][msg.sender] = true;

        if (support) {
            p.forVotes += weight;
        } else {
            p.againstVotes += weight;
        }

        emit VoteCast(proposalId, msg.sender, support, weight);
    }

    /**
     * @notice Execute a passed proposal after voting ends.
     *         Anyone can call this once voting period is over.
     */
    function execute(uint256 proposalId) external {
        Proposal storage p = proposals[proposalId];
        require(!p.executed,                        "GenomeDAO: already executed");
        require(block.number > p.endBlock,           "GenomeDAO: voting not ended");
        require(p.status == ProposalStatus.ACTIVE,  "GenomeDAO: not active");

        p.executed = true;

        bool passed = p.forVotes >= quorum && p.forVotes > p.againstVotes;

        if (passed) {
            _executeProposal(p);
            p.status = ProposalStatus.EXECUTED;
        } else {
            p.status = ProposalStatus.FAILED;
        }

        emit ProposalExecuted(proposalId, passed);
    }

    // ─────────────────────────────────────────────────────────────
    //  Internal
    // ─────────────────────────────────────────────────────────────

    function _executeProposal(Proposal storage p) internal {
        if (p.pType == ProposalType.SET_MUTATION_RATE) {
            IGenOps(genOps).setMutationRate(p.value);

        } else if (p.pType == ProposalType.SET_EPOCH_LENGTH) {
            IEvolutionClock(evoClock).setEpochLength(p.value);

        } else if (p.pType == ProposalType.SET_EXTINCTION_THRESHOLD) {
            uint8 deployment = IModelGenome(genome).DEPLOYMENT_THRESHOLD();
            IModelGenome(genome).setThresholds(uint8(p.value), deployment);

        } else if (p.pType == ProposalType.SET_DEPLOYMENT_THRESHOLD) {
            uint8 extinction = IModelGenome(genome).EXTINCTION_THRESHOLD();
            IModelGenome(genome).setThresholds(extinction, uint8(p.value));

        } else if (p.pType == ProposalType.SET_MIN_STAKE) {
            require(agentRegistry != address(0), "GenomeDAO: agent registry unset");
            IAgentRegistry(agentRegistry).setMinStake(p.value);
        }
        // CUSTOM is intentionally disabled until arbitrary-call governance is implemented.
    }

    function _validateProposal(ProposalType pType, uint256 value) internal view {
        require(pType != ProposalType.CUSTOM, "GenomeDAO: custom disabled");

        if (pType == ProposalType.SET_MUTATION_RATE) {
            require(value <= 10000, "GenomeDAO: mutation > 100%");

        } else if (pType == ProposalType.SET_EPOCH_LENGTH) {
            require(value > 0, "GenomeDAO: zero epoch length");

        } else if (pType == ProposalType.SET_EXTINCTION_THRESHOLD) {
            uint8 deployment = IModelGenome(genome).DEPLOYMENT_THRESHOLD();
            require(value < deployment, "GenomeDAO: extinction >= deployment");
            require(value <= 100, "GenomeDAO: threshold > 100");

        } else if (pType == ProposalType.SET_DEPLOYMENT_THRESHOLD) {
            uint8 extinction = IModelGenome(genome).EXTINCTION_THRESHOLD();
            require(value > extinction, "GenomeDAO: deployment <= extinction");
            require(value <= 100, "GenomeDAO: threshold > 100");

        } else if (pType == ProposalType.SET_MIN_STAKE) {
            require(agentRegistry != address(0), "GenomeDAO: agent registry unset");
            require(value > 0, "GenomeDAO: zero min stake");
        }
    }

    /**
     * @notice Voting power = count of active genome NFTs owned.
     */
    function _votingPower(address voter) internal view returns (uint256 power) {
        IModelGenome g = IModelGenome(genome);
        for (uint256 s = 0; s < registeredSpecies.length; s++) {
            // Note: getSpeciesPopulation is expensive on-chain for large populations.
            // For production consider an off-chain snapshot + merkle proof approach.
            uint256[] memory pop = g.getSpeciesPopulation(registeredSpecies[s]);
            for (uint256 i = 0; i < pop.length; i++) {
                if (g.ownerOf(pop[i]) == voter && g.isActive(pop[i])) {
                    power++;
                }
            }
        }
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getProposal(uint256 id) external view returns (Proposal memory) {
        return proposals[id];
    }

    function getVotingPower(address voter) external view returns (uint256) {
        return _votingPower(voter);
    }

    function isVotingOpen(uint256 proposalId) external view returns (bool) {
        Proposal memory p = proposals[proposalId];
        return p.status == ProposalStatus.ACTIVE && block.number <= p.endBlock;
    }
}

contracts/GenomeMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IERC721 {
function transferFrom(address from, address to, uint256 tokenId) external;
function ownerOf(uint256 tokenId) external view returns (address);
function getApproved(uint256 tokenId) external view returns (address);
function isApprovedForAll(address owner, address operator) external view returns (bool);
}

/**
 * @title GenomeMarket
 * @notice Buy, sell, and rent genome NFTs. Sellers list at a fixed price.
 *         Platform takes a cut of every sale. Rental grants temporary usage rights.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _genome        : address of ModelGenome
 *   _treasury      : TREASURY_ADDRESS
 *   _platformFeeBps: basis points platform fee (e.g. 250 = 2.5%)
 *
 * DEPLOY ORDER: After ModelGenome.
 */
contract GenomeMarket {

    // ─────────────────────────────────────────────────────────────
    //  Interfaces
    // ─────────────────────────────────────────────────────────────



    // ─────────────────────────────────────────────────────────────
    //  Data structures
    // ─────────────────────────────────────────────────────────────

    struct Listing {
        address seller;
        uint256 price;      // OG wei
        bool    active;
    }

    struct Rental {
        address renter;
        uint256 expiresAt;  // block number
        uint256 pricePerBlock; // OG wei per block
    }

    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    mapping(uint256 => Listing) public listings;  // genomeId => Listing
    mapping(uint256 => Rental)  public rentals;   // genomeId => Rental
    mapping(uint256 => uint256) public rentalPrices; // genomeId => OG wei per block

    address public genome;
    address public treasury;
    address public owner;

    uint256 public platformFeeBps; // e.g. 250 = 2.5%

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event Listed(uint256 indexed genomeId, address seller, uint256 price);
    event Delisted(uint256 indexed genomeId, address seller);
    event Sold(uint256 indexed genomeId, address seller, address buyer, uint256 price);
    event Rented(uint256 indexed genomeId, address renter, uint256 expiresAt, uint256 totalPaid);
    event RentalExpired(uint256 indexed genomeId);
    event RentalPriceSet(uint256 indexed genomeId, uint256 pricePerBlock);
    event FeeUpdated(uint256 newFeeBps);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "GenomeMarket: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _genome,
        address _treasury,
        uint256 _platformFeeBps
    ) {
        require(_genome   != address(0), "zero genome");
        require(_treasury != address(0), "zero treasury");
        require(_platformFeeBps <= 1000, "GenomeMarket: fee too high (max 10%)");

        genome         = _genome;
        treasury       = _treasury;
        platformFeeBps = _platformFeeBps;
        owner          = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function setPlatformFee(uint256 _feeBps) external onlyOwner {
        require(_feeBps <= 1000, "GenomeMarket: max 10%");
        platformFeeBps = _feeBps;
        emit FeeUpdated(_feeBps);
    }

    // ─────────────────────────────────────────────────────────────
    //  Listing
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice List a genome NFT for sale. Caller must approve this contract first.
     *         Call ModelGenome.approve(marketAddress, genomeId) before listing.
     *
     * @param genomeId  Token ID to list
     * @param price     Sale price in OG wei
     */
    function list(uint256 genomeId, uint256 price) external {
        IERC721 nft = IERC721(genome);
        require(nft.ownerOf(genomeId) == msg.sender, "GenomeMarket: not owner");
        require(
            nft.getApproved(genomeId) == address(this) ||
            nft.isApprovedForAll(msg.sender, address(this)),
            "GenomeMarket: not approved"
        );
        require(price > 0, "GenomeMarket: zero price");
        require(!listings[genomeId].active, "GenomeMarket: already listed");
        require(!_isRented(genomeId), "GenomeMarket: rented");

        nft.transferFrom(msg.sender, address(this), genomeId);

        listings[genomeId] = Listing({
            seller: msg.sender,
            price:  price,
            active: true
        });

        emit Listed(genomeId, msg.sender, price);
    }

    function delist(uint256 genomeId) external {
        Listing storage l = listings[genomeId];
        require(l.active,             "GenomeMarket: not listed");
        require(l.seller == msg.sender || msg.sender == owner, "GenomeMarket: unauthorized");
        address seller = l.seller;
        l.active = false;
        IERC721(genome).transferFrom(address(this), seller, genomeId);
        emit Delisted(genomeId, seller);
    }

    function setRentalPrice(uint256 genomeId, uint256 pricePerBlock) external {
        IERC721 nft = IERC721(genome);
        require(nft.ownerOf(genomeId) == msg.sender, "GenomeMarket: not owner");
        require(!listings[genomeId].active, "GenomeMarket: listed for sale");
        rentalPrices[genomeId] = pricePerBlock;
        emit RentalPriceSet(genomeId, pricePerBlock);
    }

    /**
     * @notice Buy a listed genome NFT. Send exact price as msg.value.
     */
    function buy(uint256 genomeId) external payable {
        Listing storage l = listings[genomeId];
        require(l.active,           "GenomeMarket: not listed");
        require(msg.value >= l.price, "GenomeMarket: insufficient payment");
        require(!_isRented(genomeId), "GenomeMarket: rented");

        address seller = l.seller;
        uint256 price  = l.price;

        l.active = false;

        uint256 fee       = (price * platformFeeBps) / 10000;
        uint256 sellerAmt = price - fee;

        // Listed NFTs are held in escrow by this contract.
        IERC721(genome).transferFrom(address(this), msg.sender, genomeId);

        // Pay seller and treasury
        _sendValue(seller, sellerAmt);
        _sendValue(treasury, fee);

        // Refund excess
        if (msg.value > price) {
            _sendValue(msg.sender, msg.value - price);
        }

        emit Sold(genomeId, seller, msg.sender, price);
    }

    // ─────────────────────────────────────────────────────────────
    //  Rental
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Rent a genome for a number of blocks. The genome NFT stays with
     *         the owner — rental records usage rights only.
     *
     * @param genomeId       Token ID to rent
     * @param blocks         Number of blocks to rent for
     */
    function rent(
        uint256 genomeId,
        uint256 blocks
    ) external payable {
        require(blocks > 0,           "GenomeMarket: zero blocks");
        uint256 pricePerBlock = rentalPrices[genomeId];
        require(pricePerBlock > 0,    "GenomeMarket: zero price");
        require(!listings[genomeId].active, "GenomeMarket: listed for sale");

        uint256 totalCost = blocks * pricePerBlock;
        require(msg.value >= totalCost, "GenomeMarket: insufficient payment");

        // Ensure no active rental
        Rental memory existing = rentals[genomeId];
        require(
            existing.renter == address(0) || block.number > existing.expiresAt,
            "GenomeMarket: already rented"
        );

        address nftOwner = IERC721(genome).ownerOf(genomeId);
        require(nftOwner != address(0), "GenomeMarket: genome not exist");

        uint256 fee      = (totalCost * platformFeeBps) / 10000;
        uint256 ownerAmt = totalCost - fee;

        rentals[genomeId] = Rental({
            renter:       msg.sender,
            expiresAt:    block.number + blocks,
            pricePerBlock: pricePerBlock
        });

        _sendValue(nftOwner, ownerAmt);
        _sendValue(treasury, fee);

        if (msg.value > totalCost) {
            _sendValue(msg.sender, msg.value - totalCost);
        }

        emit Rented(genomeId, msg.sender, block.number + blocks, totalCost);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getListing(uint256 genomeId) external view returns (Listing memory) {
        return listings[genomeId];
    }

    function getRental(uint256 genomeId) external view returns (Rental memory) {
        return rentals[genomeId];
    }

    function isRented(uint256 genomeId) external view returns (bool) {
        return _isRented(genomeId);
    }

    function _isRented(uint256 genomeId) internal view returns (bool) {
        Rental memory r = rentals[genomeId];
        return r.renter != address(0) && block.number <= r.expiresAt;
    }

    function currentRenter(uint256 genomeId) external view returns (address) {
        Rental memory r = rentals[genomeId];
        if (block.number <= r.expiresAt) return r.renter;
        return address(0);
    }

    function _sendValue(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = payable(to).call{value: amount}("");
        require(ok, "GenomeMarket: transfer failed");
    }
}

contracts/GenOps.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IModelGenome {
function mintChildGenome(
uint256 parentA,
uint256 parentB,
bytes32 childAdapterRoot,
bytes32 childLineageRoot,
uint256 alpha
) external returns (uint256);

function getGenome(uint256 id) external view returns (
uint256, bytes32, bytes32, uint256[] memory,
uint32, uint8, bytes32, uint8, uint256, uint256, bytes32
);

function isActive(uint256 id) external view returns (bool);
function ownerOf(uint256 tokenId) external view returns (address);
function updateAdapterRoot(uint256 genomeId, bytes32 newAdapterRoot) external;
}

/**
 * @title GenOps
 * @notice Genetic operators for the Evolution Lab.
 *         Handles selection, crossover and mutation triggers.
 *         The actual adapter weight arithmetic happens off-chain in the backend;
 *         this contract records the operation on-chain and mints child genomes.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _genome      : address(0) initially — set via setGenome() after ModelGenome deploys
 *   _evoClock    : address of EvolutionClock
 *   _treasury    : TREASURY_ADDRESS (receives breeding fees)
 *   _breedingFee : OG wei fee per crossover (e.g. 1 ether = 1 OG)
 *
 * DEPLOY ORDER: Deploy before ModelGenome (with address(0) for genome param).
 *               After ModelGenome deploys, call setGenome(modelGenomeAddress).
 */
contract GenOps {

    // ─────────────────────────────────────────────────────────────
    //  Interfaces
    // ─────────────────────────────────────────────────────────────



    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    address public genome;
    address public evoClock;
    address public treasury;
    address public owner;

    uint256 public breedingFee;    // OG wei per crossover
    uint256 public mutationRate;   // out of 10000 — e.g. 500 = 5%

    mapping(uint256 => uint256) public lastMutatedAt;    // genomeId => block
    mapping(uint256 => uint256) public crossoverCount;   // genomeId => times bred

    uint256 public MAX_BREED_COUNT = 5; // max times a genome can be a parent

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event CrossoverTriggered(
        uint256 parentA,
        uint256 parentB,
        uint256 childId,
        uint256 alpha,
        bytes32 childAdapterRoot
    );
    event MutationTriggered(uint256 indexed genomeId, bytes32 newAdapterRoot);
    event SelectionRun(uint256 generation, uint256 selectedCount);
    event GenomeSet(address genome);
    event BreedingFeeUpdated(uint256 newFee);
    event MutationRateUpdated(uint256 newRate);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "GenOps: not owner");
        _;
    }

    modifier onlyClock() {
        require(msg.sender == evoClock, "GenOps: only EvolutionClock");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _evoClock,
        address _treasury,
        uint256 _breedingFee,
        uint256 _mutationRate
    ) {
        require(_treasury != address(0), "zero treasury");
        require(_evoClock != address(0), "zero evoClock");
        require(_mutationRate <= 10000, "GenOps: rate > 100%");
        evoClock     = _evoClock;
        treasury     = _treasury;
        breedingFee  = _breedingFee;
        mutationRate = _mutationRate;
        owner        = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function setGenome(address _genome) external onlyOwner {
        require(_genome != address(0), "zero genome");
        genome = _genome;
        emit GenomeSet(_genome);
    }

    function setBreedingFee(uint256 _fee) external onlyOwner {
        breedingFee = _fee;
        emit BreedingFeeUpdated(_fee);
    }

    function setMutationRate(uint256 _rate) external onlyOwner {
        require(_rate <= 10000, "GenOps: rate > 100%");
        mutationRate = _rate;
        emit MutationRateUpdated(_rate);
    }

    function setMaxBreedCount(uint256 _max) external onlyOwner {
        MAX_BREED_COUNT = _max;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "GenOps: zero owner");
        address previous = owner;
        owner = newOwner;
        emit OwnershipTransferred(previous, newOwner);
    }

    // ─────────────────────────────────────────────────────────────
    //  Genetic operators
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Trigger arithmetic crossover of two parent genomes.
     *         Backend computes childAdapterRoot off-chain (arithmetic interpolation
     *         of adapter weights: child = alpha*parentA + (1-alpha)*parentB),
     *         uploads to 0G Storage, then calls this function with the root hash.
     *
     * @param parentA           Token ID of parent A (higher fitness)
     * @param parentB           Token ID of parent B
     * @param childAdapterRoot  0G Storage root of merged adapter
     * @param childLineageRoot  Merkle root of child's ancestry
     * @param alpha             Mixing ratio * 100 (0–100, e.g. 60 = 60% from A)
     */
    function crossover(
        uint256 parentA,
        uint256 parentB,
        bytes32 childAdapterRoot,
        bytes32 childLineageRoot,
        uint256 alpha
    ) external payable returns (uint256 childId) {
        require(genome != address(0),              "GenOps: genome not set");
        require(msg.value >= breedingFee,          "GenOps: insufficient breeding fee");
        require(alpha <= 100,                      "GenOps: alpha out of range");
        require(parentA != parentB,                "GenOps: same parent");
        require(childAdapterRoot != bytes32(0),    "GenOps: zero child root");
        require(IModelGenome(genome).isActive(parentA), "GenOps: parentA not active");
        require(IModelGenome(genome).isActive(parentB), "GenOps: parentB not active");
        require(crossoverCount[parentA] < MAX_BREED_COUNT, "GenOps: parentA over breed limit");
        require(crossoverCount[parentB] < MAX_BREED_COUNT, "GenOps: parentB over breed limit");

        crossoverCount[parentA]++;
        crossoverCount[parentB]++;

        // Breeding fee to treasury
        payable(treasury).transfer(msg.value);

        childId = IModelGenome(genome).mintChildGenome(
            parentA, parentB, childAdapterRoot, childLineageRoot, alpha
        );

        emit CrossoverTriggered(parentA, parentB, childId, alpha, childAdapterRoot);
    }

    /**
     * @notice Apply Gaussian mutation to a genome's adapter.
     *         Backend mutates adapter weights off-chain, uploads new adapter
     *         to 0G Storage, and calls this with the new root hash.
     *
     * @param genomeId       Token ID to mutate
     * @param newAdapterRoot New 0G Storage root after mutation
     */
    function mutate(
        uint256 genomeId,
        bytes32 newAdapterRoot
    ) external {
        require(genome != address(0), "GenOps: genome not set");
        require(IModelGenome(genome).isActive(genomeId), "GenOps: genome not active");
        require(newAdapterRoot != bytes32(0), "GenOps: zero adapter root");
        require(
            msg.sender == owner || IModelGenome(genome).ownerOf(genomeId) == msg.sender,
            "GenOps: not genome owner"
        );

        lastMutatedAt[genomeId] = block.number;
        IModelGenome(genome).updateAdapterRoot(genomeId, newAdapterRoot);
        emit MutationTriggered(genomeId, newAdapterRoot);
    }

    /**
     * @notice Called by EvolutionClock each epoch. Backend listens to this event
     *         and runs selection + crossover + mutation off-chain.
     * @param generation Current generation number from EvolutionClock
     */
    function runEpoch(uint256 generation) external onlyClock {
        emit SelectionRun(generation, 0); // backend fills actual selectedCount in response
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getBreedCount(uint256 genomeId) external view returns (uint256) {
        return crossoverCount[genomeId];
    }

    function canBreed(uint256 genomeId) external view returns (bool) {
        return crossoverCount[genomeId] < MAX_BREED_COUNT
            && IModelGenome(genome).isActive(genomeId);
    }
}

contracts/InferencePool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IModelGenome {
function getGenome(uint256 id) external view returns (
uint256 genomeId,
bytes32 baseModelId,
bytes32 adapterStorageRoot,
uint256[] memory parentIds,
uint32  generation,
uint8   fitnessScore,
bytes32 lineageRoot,
uint8   status,
uint256 inferenceRevenue,
uint256 mintedAt,
bytes32 speciesId
);
function ownerOf(uint256 tokenId) external view returns (address);
function accrueRevenue(uint256 genomeId, uint256 amount) external;
}

/**
 * @title InferencePool
 * @notice Deploys high-fitness genomes (score >= DEPLOYMENT_THRESHOLD) to 0G Compute
 *         and distributes earned inference revenue back to genome NFT holders.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _genome   : address of ModelGenome
 *   _treasury : TREASURY_ADDRESS (receives platform cut of inference revenue)
 *   _platformShare : basis points for platform (e.g. 1000 = 10%)
 *
 * DEPLOY ORDER: After ModelGenome.
 */
contract InferencePool {

    // ─────────────────────────────────────────────────────────────
    //  Interface
    // ─────────────────────────────────────────────────────────────



    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    address public genome;
    address public treasury;
    address public owner;

    uint256 public platformShare; // basis points out of 10000
    uint256 public holderShare;   // 10000 - platformShare

    mapping(uint256 => bool)    public deployed;           // genomeId => in pool
    mapping(uint256 => bool)    public knownPoolGenome;    // genomeId => ever added to array
    mapping(uint256 => uint256) public pendingRewards;     // genomeId => claimable OG
    mapping(uint256 => uint256) public totalEarned;        // genomeId => lifetime earnings

    uint256[] public deployedGenomes;

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event GenomeDeployedToPool(uint256 indexed genomeId);
    event GenomeRemovedFromPool(uint256 indexed genomeId);
    event RevenueDistributed(uint256 indexed genomeId, uint256 holderAmount, uint256 platformAmount);
    event RewardClaimed(uint256 indexed genomeId, address holder, uint256 amount);
    event RevenueReceived(uint256 indexed genomeId, uint256 amount);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "InferencePool: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _genome,
        address _treasury,
        uint256 _platformShare
    ) {
        require(_genome   != address(0), "zero genome");
        require(_treasury != address(0), "zero treasury");
        require(_platformShare <= 3000,  "InferencePool: platform share too high (max 30%)");

        genome         = _genome;
        treasury       = _treasury;
        platformShare  = _platformShare;
        holderShare    = 10000 - _platformShare;
        owner          = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Pool management
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Add a deployed genome to the inference pool.
     *         Any wallet can add a DEPLOYED-status genome after ModelGenome
     *         emits GenomeDeployed. This keeps pool enrollment permissionless;
     *         the offchain compute operator can still decide which endpoints to serve.
     */
    function addToPool(uint256 genomeId) external {
        require(!deployed[genomeId], "InferencePool: already in pool");

        // Verify genome is DEPLOYED status (status = 2). The threshold lives in
        // ModelGenome governance, so this contract should not hardcode it.
        (, , , , , , , uint8 status, , , ) =
            IModelGenome(genome).getGenome(genomeId);
        require(status == 2,          "InferencePool: genome not DEPLOYED");

        deployed[genomeId] = true;
        if (!knownPoolGenome[genomeId]) {
            knownPoolGenome[genomeId] = true;
            deployedGenomes.push(genomeId);
        }

        emit GenomeDeployedToPool(genomeId);
    }

    function removeFromPool(uint256 genomeId) external onlyOwner {
        require(deployed[genomeId], "InferencePool: not in pool");
        deployed[genomeId] = false;
        emit GenomeRemovedFromPool(genomeId);
    }

    // ─────────────────────────────────────────────────────────────
    //  Revenue distribution
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Called by backend when a deployed genome earns inference revenue.
     *         Send OG as msg.value — split between holder and platform treasury.
     *
     * @param genomeId  Token ID that earned the revenue
     */
    function distributeRevenue(uint256 genomeId) external payable {
        require(deployed[genomeId], "InferencePool: genome not in pool");
        require(msg.value > 0,      "InferencePool: zero revenue");

        uint256 platformAmt = (msg.value * platformShare) / 10000;
        uint256 holderAmt   = msg.value - platformAmt;

        pendingRewards[genomeId] += holderAmt;
        totalEarned[genomeId]    += msg.value;

        _sendValue(treasury, platformAmt);

        // Record on genome NFT
        IModelGenome(genome).accrueRevenue(genomeId, msg.value);

        emit RevenueDistributed(genomeId, holderAmt, platformAmt);
        emit RevenueReceived(genomeId, msg.value);
    }

    /**
     * @notice NFT holder claims accumulated inference rewards.
     * @param genomeId  Token ID to claim rewards for
     */
    function claimReward(uint256 genomeId) external {
        address holder = IModelGenome(genome).ownerOf(genomeId);
        require(msg.sender == holder, "InferencePool: not genome owner");

        uint256 reward = pendingRewards[genomeId];
        require(reward > 0, "InferencePool: nothing to claim");

        pendingRewards[genomeId] = 0;
        _sendValue(holder, reward);

        emit RewardClaimed(genomeId, holder, reward);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getPendingReward(uint256 genomeId) external view returns (uint256) {
        return pendingRewards[genomeId];
    }

    function getDeployedGenomes() external view returns (uint256[] memory) {
        return deployedGenomes;
    }

    function isDeployed(uint256 genomeId) external view returns (bool) {
        return deployed[genomeId];
    }

    function _sendValue(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = payable(to).call{value: amount}("");
        require(ok, "InferencePool: transfer failed");
    }

    receive() external payable {}
}

contracts/MeshEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title MeshEscrow
 * @notice Holds OG tokens for each DAG task node. Releases to the agent on
 *         TEE approval, or refunds to requester on timeout/failure.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _dagRegistry  : address of TaskDAGRegistry
 *   _teeVerifier  : address of TEEVerifierBridge
 *   _revenueRouter: address of RevenueRouter
 *
 * DEPLOY ORDER: Deploy MeshEscrow BEFORE AgentRegistry (AgentRegistry needs escrow address).
 * Then after deploying RevenueRouter and TEEVerifierBridge, call:
 *   setRevenueRouter(revenueRouterAddress)
 *   setTeeVerifier(teeVerifierAddress)
 *   setDagRegistry(dagRegistryAddress)
 */
contract MeshEscrow {

    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    mapping(bytes32 => uint256) public nodeBudgets;    // taskId => OG locked (wei)
    mapping(bytes32 => bool)    public released;        // taskId => already settled
    mapping(bytes32 => address) public taskRequester;   // taskId => who to refund

    address public dagRegistry;
    address public teeVerifier;
    address public revenueRouter;
    address public owner;

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event FundsLocked(bytes32 indexed dagRoot, uint256 totalAmount);
    event NodeReleased(bytes32 indexed taskId, address agent, uint256 amount);
    event NodeRefunded(bytes32 indexed taskId, address requester, uint256 amount);
    event AddressUpdated(string slot, address newAddress);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyDAG() {
        require(msg.sender == dagRegistry, "MeshEscrow: only DAGRegistry");
        _;
    }

    modifier onlyTEE() {
        require(msg.sender == teeVerifier, "MeshEscrow: only TEEVerifier");
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "MeshEscrow: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor() {
        owner = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin setters (called after dependent contracts deploy)
    // ─────────────────────────────────────────────────────────────

    function setDagRegistry(address _dagRegistry) external onlyOwner {
        require(_dagRegistry != address(0), "zero address");
        dagRegistry = _dagRegistry;
        emit AddressUpdated("dagRegistry", _dagRegistry);
    }

    function setTeeVerifier(address _teeVerifier) external onlyOwner {
        require(_teeVerifier != address(0), "zero address");
        teeVerifier = _teeVerifier;
        emit AddressUpdated("teeVerifier", _teeVerifier);
    }

    function setRevenueRouter(address _revenueRouter) external onlyOwner {
        require(_revenueRouter != address(0), "zero address");
        revenueRouter = _revenueRouter;
        emit AddressUpdated("revenueRouter", _revenueRouter);
    }

    // ─────────────────────────────────────────────────────────────
    //  Core logic
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Called by TaskDAGRegistry when a DAG is submitted.
     *         Locks OG per task node. msg.value must equal sum of budgets.
     */
    function lockFunds(
        bytes32          dagRoot,
        bytes32[] calldata taskIds,
        uint256[] calldata budgets,
        address          requester
    ) external payable onlyDAG {
        require(taskIds.length == budgets.length, "MeshEscrow: length mismatch");

        uint256 total = 0;
        for (uint256 i = 0; i < taskIds.length; i++) {
            require(taskIds[i] != bytes32(0), "MeshEscrow: zero taskId");
            require(budgets[i] > 0, "MeshEscrow: zero budget");
            require(nodeBudgets[taskIds[i]] == 0, "MeshEscrow: task already funded");
            nodeBudgets[taskIds[i]]  = budgets[i];
            taskRequester[taskIds[i]] = requester;
            total += budgets[i];
        }
        require(msg.value == total, "MeshEscrow: budget mismatch");

        emit FundsLocked(dagRoot, total);
    }

    /**
     * @notice Called by TEEVerifierBridge when work passes. Sends payment
     *         to RevenueRouter which splits it between agent/stakers/treasury.
     */
    function release(bytes32 taskId, address agent) external onlyTEE {
        require(!released[taskId], "MeshEscrow: already settled");
        released[taskId] = true;

        uint256 amount = nodeBudgets[taskId];
        require(amount > 0, "MeshEscrow: zero budget");
        require(revenueRouter != address(0), "MeshEscrow: revenue router unset");

        // Send to RevenueRouter for splitting, forward agent address
        (bool ok, ) = revenueRouter.call{value: amount}(
            abi.encodeWithSignature("route(address)", agent)
        );
        require(ok, "MeshEscrow: revenue router call failed");

        emit NodeReleased(taskId, agent, amount);
    }

    /**
     * @notice Called by TaskDAGRegistry on timeout. Refunds requester.
     */
    function refundOnTimeout(bytes32 taskId) external onlyDAG {
        require(!released[taskId], "MeshEscrow: already settled");
        released[taskId] = true;

        uint256 amount  = nodeBudgets[taskId];
        address requester = taskRequester[taskId];
        require(amount > 0,            "MeshEscrow: zero budget");
        require(requester != address(0), "MeshEscrow: unknown requester");

        _sendValue(requester, amount);
        emit NodeRefunded(taskId, requester, amount);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getBudget(bytes32 taskId) external view returns (uint256) {
        return nodeBudgets[taskId];
    }

    function isReleased(bytes32 taskId) external view returns (bool) {
        return released[taskId];
    }

    function _sendValue(address to, uint256 amount) internal {
        (bool ok, ) = payable(to).call{value: amount}("");
        require(ok, "MeshEscrow: transfer failed");
    }

    receive() external payable {}
}

contracts/ModelGenome.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// OpenZeppelin — install: npm install @openzeppelin/contracts
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ModelGenome
 * @notice ERC-7857 Intelligent NFT. Every AI model in the Evolution Lab
 *         is represented as a genome NFT with encrypted adapter weights
 *         stored on 0G Storage. Fitness scoring drives extinction or deployment.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _fitnessOracle : address of FitnessOracle
 *   _genOps        : address of GenOps
 *   _treasury      : TREASURY_ADDRESS (receives mint fees)
 *
 * DEPLOY ORDER: After FitnessOracle and GenOps are deployed.
 *               FitnessOracle and GenOps are deployed with address(0) for genome,
 *               then updated via their setGenome() functions after this deploys.
 */
contract ModelGenome is ERC721, Ownable {

    // ─────────────────────────────────────────────────────────────
    //  Enums
    // ─────────────────────────────────────────────────────────────

    enum GenomeStatus { ACTIVE, EXTINCT, DEPLOYED }

    // ─────────────────────────────────────────────────────────────
    //  Data structures
    // ─────────────────────────────────────────────────────────────

    struct Genome {
        uint256      genomeId;
        bytes32      baseModelId;        // hash identifying the foundation model
        bytes32      adapterStorageRoot; // 0G Storage root hash of encrypted LoRA adapter
        uint256[]    parentIds;          // empty for seed genomes
        uint32       generation;         // 0 = seed
        uint8        fitnessScore;       // 0–100, updated by FitnessOracle
        bytes32      lineageRoot;        // Merkle root of ancestry chain
        GenomeStatus status;
        uint256      inferenceRevenue;   // cumulative OG earned from InferencePool
        uint256      mintedAt;           // block number
        bytes32      speciesId;          // writing | code | reasoning | creative
    }

    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    mapping(uint256 => Genome)      public genomes;
    mapping(bytes32 => uint256[])   public speciesPopulation; // speciesId => genomeIds[]

    uint256 public nextId    = 1;
    uint256 public mintFee   = 5 ether;  // 5 OG — updateable by owner

    address public fitnessOracle;
    address public genOps;
    address public inferencePool;
    address public treasury;

    uint8 public EXTINCTION_THRESHOLD  = 45;  // below this → EXTINCT
    uint8 public DEPLOYMENT_THRESHOLD  = 88;  // above this → DEPLOYED

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event GenomeMinted(uint256 indexed id, address owner, bytes32 speciesId, uint32 generation);
    event FitnessUpdated(uint256 indexed id, uint8 score, uint256 blockNumber);
    event GenomeExtinct(uint256 indexed id);
    event GenomeDeployed(uint256 indexed id);
    event Crossover(uint256 parentA, uint256 parentB, uint256 childId, uint256 alpha);
    event RevenueAccrued(uint256 indexed id, uint256 amount);
    event AdapterRootUpdated(uint256 indexed id, bytes32 adapterStorageRoot);
    event OraclesUpdated(address fitnessOracle, address genOps);
    event InferencePoolSet(address inferencePool);
    event ThresholdsUpdated(uint8 extinction, uint8 deployment);
    event MintFeeUpdated(uint256 newFee);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyFitnessOracle() {
        require(msg.sender == fitnessOracle, "ModelGenome: only fitness oracle");
        _;
    }

    modifier onlyGenOps() {
        require(msg.sender == genOps, "ModelGenome: only genOps");
        _;
    }

    modifier onlyInferencePool() {
        require(msg.sender == inferencePool, "ModelGenome: only inference pool");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _fitnessOracle,
        address _genOps,
        address _treasury
    ) ERC721("SynapseMesh Genome", "GENOME") Ownable(msg.sender) {
        require(_fitnessOracle != address(0), "zero oracle");
        require(_genOps        != address(0), "zero genOps");
        require(_treasury      != address(0), "zero treasury");

        fitnessOracle = _fitnessOracle;
        genOps        = _genOps;
        treasury      = _treasury;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function setMintFee(uint256 _fee) external onlyOwner {
        mintFee = _fee;
        emit MintFeeUpdated(_fee);
    }

    function setThresholds(uint8 _extinction, uint8 _deployment) external onlyOwner {
        require(_extinction < _deployment, "ModelGenome: invalid thresholds");
        require(_deployment <= 100, "ModelGenome: threshold > 100");
        EXTINCTION_THRESHOLD = _extinction;
        DEPLOYMENT_THRESHOLD = _deployment;
        emit ThresholdsUpdated(_extinction, _deployment);
    }

    function setOracles(address _fitnessOracle, address _genOps) external onlyOwner {
        require(_fitnessOracle != address(0), "zero oracle");
        require(_genOps != address(0), "zero genOps");
        fitnessOracle = _fitnessOracle;
        genOps        = _genOps;
        emit OraclesUpdated(_fitnessOracle, _genOps);
    }

    function setInferencePool(address _inferencePool) external onlyOwner {
        require(_inferencePool != address(0), "zero inferencePool");
        inferencePool = _inferencePool;
        emit InferencePoolSet(_inferencePool);
    }

    // ─────────────────────────────────────────────────────────────
    //  Minting
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Mint a seed genome NFT. Anyone can call this by paying mintFee OG.
     *
     * @param baseModelId        keccak256 of foundation model identifier string
     *                           e.g. keccak256("meta-llama/Llama-3.1-8B")
     * @param adapterStorageRoot Root hash returned by 0G Storage after uploading
     *                           encrypted LoRA adapter weights
     * @param speciesId          keccak256 of species string:
     *                           keccak256("writing") | keccak256("code") |
     *                           keccak256("reasoning") | keccak256("creative")
     */
    function mintSeedGenome(
        bytes32 baseModelId,
        bytes32 adapterStorageRoot,
        bytes32 speciesId
    ) external payable returns (uint256) {
        require(msg.value >= mintFee, "ModelGenome: insufficient mint fee");

        uint256 id = nextId++;

        genomes[id] = Genome({
            genomeId:           id,
            baseModelId:        baseModelId,
            adapterStorageRoot: adapterStorageRoot,
            parentIds:          new uint256[](0),
            generation:         0,
            fitnessScore:       0,
            lineageRoot:        bytes32(0),
            status:             GenomeStatus.ACTIVE,
            inferenceRevenue:   0,
            mintedAt:           block.number,
            speciesId:          speciesId
        });

        speciesPopulation[speciesId].push(id);
        _mint(msg.sender, id);

        _sendValue(treasury, msg.value);

        emit GenomeMinted(id, msg.sender, speciesId, 0);
        return id;
    }

    /**
     * @notice Mint a child genome from crossover. Called by GenOps only.
     *
     * @param parentA           Token ID of parent A
     * @param parentB           Token ID of parent B
     * @param childAdapterRoot  0G Storage root of the child's merged adapter
     * @param childLineageRoot  Merkle root of child's ancestry tree
     * @param alpha             Crossover mixing ratio * 100 (e.g. 60 = 60% from A)
     */
    function mintChildGenome(
        uint256 parentA,
        uint256 parentB,
        bytes32 childAdapterRoot,
        bytes32 childLineageRoot,
        uint256 alpha
    ) external onlyGenOps returns (uint256) {
        require(_ownerOf(parentA) != address(0), "ModelGenome: parentA not exist");
        require(_ownerOf(parentB) != address(0), "ModelGenome: parentB not exist");
        require(childAdapterRoot != bytes32(0), "ModelGenome: zero adapter root");

        Genome storage pA = genomes[parentA];

        uint256 id = nextId++;
        uint256[] memory parents = new uint256[](2);
        parents[0] = parentA;
        parents[1] = parentB;

        genomes[id] = Genome({
            genomeId:           id,
            baseModelId:        pA.baseModelId,
            adapterStorageRoot: childAdapterRoot,
            parentIds:          parents,
            generation:         pA.generation + 1,
            fitnessScore:       0,
            lineageRoot:        childLineageRoot,
            status:             GenomeStatus.ACTIVE,
            inferenceRevenue:   0,
            mintedAt:           block.number,
            speciesId:          pA.speciesId
        });

        speciesPopulation[pA.speciesId].push(id);
        _mint(ownerOf(parentA), id); // child minted to parent A's owner

        emit Crossover(parentA, parentB, id, alpha);
        emit GenomeMinted(id, ownerOf(parentA), pA.speciesId, pA.generation + 1);
        return id;
    }

    // ─────────────────────────────────────────────────────────────
    //  Fitness — called by FitnessOracle
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Update genome fitness score. Called by FitnessOracle after TEE evaluation.
     * @param genomeId  Token ID
     * @param score     0–100 fitness score from TEE
     */
    function submitFitness(uint256 genomeId, uint8 score) external onlyFitnessOracle {
        Genome storage g = genomes[genomeId];
        require(_ownerOf(genomeId) != address(0), "ModelGenome: genome not exist");
        require(g.status == GenomeStatus.ACTIVE, "ModelGenome: not active");
        require(score <= 100, "ModelGenome: score > 100");

        g.fitnessScore = score;
        emit FitnessUpdated(genomeId, score, block.number);

        if (score < EXTINCTION_THRESHOLD) {
            g.status = GenomeStatus.EXTINCT;
            emit GenomeExtinct(genomeId);
        } else if (score >= DEPLOYMENT_THRESHOLD) {
            g.status = GenomeStatus.DEPLOYED;
            emit GenomeDeployed(genomeId);
        }
    }

    /// @notice Called by InferencePool to record earnings
    function accrueRevenue(uint256 genomeId, uint256 amount) external onlyInferencePool {
        require(_ownerOf(genomeId) != address(0), "ModelGenome: genome not exist");
        genomes[genomeId].inferenceRevenue += amount;
        emit RevenueAccrued(genomeId, amount);
    }

    /// @notice Called by GenOps after a genome owner commits a mutation result.
    function updateAdapterRoot(uint256 genomeId, bytes32 newAdapterRoot) external onlyGenOps {
        require(_ownerOf(genomeId) != address(0), "ModelGenome: genome not exist");
        require(genomes[genomeId].status == GenomeStatus.ACTIVE, "ModelGenome: not active");
        require(newAdapterRoot != bytes32(0), "ModelGenome: zero adapter root");
        genomes[genomeId].adapterStorageRoot = newAdapterRoot;
        emit AdapterRootUpdated(genomeId, newAdapterRoot);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getGenome(uint256 genomeId) external view returns (Genome memory) {
        return genomes[genomeId];
    }

    function getSpeciesPopulation(bytes32 speciesId) external view returns (uint256[] memory) {
        return speciesPopulation[speciesId];
    }

    function getSpeciesCount(bytes32 speciesId) external view returns (uint256) {
        return speciesPopulation[speciesId].length;
    }

    function isActive(uint256 genomeId) external view returns (bool) {
        return _ownerOf(genomeId) != address(0) && genomes[genomeId].status == GenomeStatus.ACTIVE;
    }

    function _sendValue(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = payable(to).call{value: amount}("");
        require(ok, "ModelGenome: transfer failed");
    }
}

contracts/TaskDAGRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IMeshEscrow {
function lockFunds(
bytes32 dagRoot,
bytes32[] calldata taskIds,
uint256[] calldata budgets,
address requester
) external payable;
function refundOnTimeout(bytes32 taskId) external;
}

/**
 * @title TaskDAGRegistry
 * @notice Stores Task DAG structures on 0G Chain. Validates topology (no cycles),
 *         manages node state transitions, and triggers escrow on submission.
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _bidEngine   : address of BidEngine
 *   _teeVerifier : address of TEEVerifierBridge
 *   _meshEscrow  : address of MeshEscrow
 *
 * DEPLOY ORDER: After BidEngine and MeshEscrow. Before TEEVerifierBridge.
 * After deploying TEEVerifierBridge, call setTeeVerifier(teeVerifierAddress).
 */
contract TaskDAGRegistry {

    // ─────────────────────────────────────────────────────────────
    //  Enums
    // ─────────────────────────────────────────────────────────────

    enum NodeType   { SEQUENTIAL, PARALLEL, CONDITIONAL, REDUCE }
    enum NodeStatus { PENDING, BIDDING, ASSIGNED, RUNNING, COMPLETE, FAILED }

    // ─────────────────────────────────────────────────────────────
    //  Data structures
    // ─────────────────────────────────────────────────────────────

    struct TaskNode {
        bytes32    taskId;
        bytes32    inputSchemaHash;    // hash of full spec stored on 0G Storage
        bytes32    outputSchemaHash;
        bytes32    qualityRubricHash;  // TEE verifier reads rubric from 0G KV
        bytes32[]  dependsOn;          // upstream taskIds (must all be COMPLETE first)
        NodeType   nodeType;
        uint256    maxBudget;          // OG wei budget for this node
        uint256    timeoutBlocks;      // blocks before node can be marked failed
        address    assignedAgent;
        NodeStatus status;
        uint256    assignedAt;
        uint256    completedAt;
    }

    struct DAG {
        bytes32 dagRoot;
        address requester;
        uint256 totalBudget;
        uint256 submittedAt;
        uint256 nodeCount;
        bool    complete;
    }

    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    mapping(bytes32 => DAG)          public dags;
    mapping(bytes32 => TaskNode)     public nodes;
    mapping(bytes32 => bytes32[])    public dagNodes;   // dagRoot => taskId[]
    mapping(bytes32 => bytes32)      public nodeToDag;   // taskId => dagRoot

    address public bidEngine;
    address public teeVerifier;
    address public meshEscrow;
    address public owner;

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event DAGSubmitted(bytes32 indexed dagRoot, address requester, uint256 nodeCount, uint256 budget);
    event NodeStatusChanged(bytes32 indexed taskId, NodeStatus newStatus, address agent);
    event DAGCompleted(bytes32 indexed dagRoot);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyBidEngine() {
        require(msg.sender == bidEngine, "DAGRegistry: only BidEngine");
        _;
    }

    modifier onlyTEE() {
        require(msg.sender == teeVerifier, "DAGRegistry: only TEEVerifier");
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "DAGRegistry: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Interfaces
    // ─────────────────────────────────────────────────────────────



    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _bidEngine,
        address _meshEscrow
    ) {
        require(_bidEngine  != address(0), "zero bidEngine");
        require(_meshEscrow != address(0), "zero meshEscrow");
        bidEngine   = _bidEngine;
        meshEscrow  = _meshEscrow;
        owner       = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function setTeeVerifier(address _teeVerifier) external onlyOwner {
        require(_teeVerifier != address(0), "zero verifier");
        teeVerifier = _teeVerifier;
    }

    // ─────────────────────────────────────────────────────────────
    //  DAG submission
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Submit a task DAG. msg.value must equal the sum of all node maxBudgets.
     *         Nodes must be ordered so all dependsOn references appear earlier in the array.
     *
     * @param dagRoot   unique identifier for this DAG (keccak256 of requester+nonce)
     * @param taskNodes ordered array of task nodes
     */
    function submitDAG(
        bytes32          dagRoot,
        TaskNode[] calldata taskNodes
    ) external payable {
        require(dagRoot != bytes32(0), "DAGRegistry: zero dagRoot");
        require(dags[dagRoot].requester == address(0), "DAGRegistry: DAG already exists");
        require(taskNodes.length > 0,                  "DAGRegistry: empty DAG");

        _validateNoCycles(taskNodes);

        // Calculate total budget
        uint256 total = 0;
        bytes32[] memory taskIds = new bytes32[](taskNodes.length);
        uint256[] memory budgets = new uint256[](taskNodes.length);

        for (uint256 i = 0; i < taskNodes.length; i++) {
            require(taskNodes[i].taskId != bytes32(0), "DAGRegistry: zero taskId");
            require(nodeToDag[taskNodes[i].taskId] == bytes32(0), "DAGRegistry: duplicate taskId");
            require(taskNodes[i].maxBudget > 0, "DAGRegistry: zero budget");
            require(taskNodes[i].timeoutBlocks > 0, "DAGRegistry: zero timeout");
            total      += taskNodes[i].maxBudget;
            taskIds[i]  = taskNodes[i].taskId;
            budgets[i]  = taskNodes[i].maxBudget;
        }

        require(msg.value == total, "DAGRegistry: budget mismatch");

        // Store DAG metadata
        dags[dagRoot] = DAG({
            dagRoot:     dagRoot,
            requester:   msg.sender,
            totalBudget: msg.value,
            submittedAt: block.number,
            nodeCount:   taskNodes.length,
            complete:    false
        });

        // Store nodes
        for (uint256 i = 0; i < taskNodes.length; i++) {
            bytes32 taskId = taskNodes[i].taskId;
            nodes[taskId]        = taskNodes[i];
            nodes[taskId].status = taskNodes[i].dependsOn.length == 0
                ? NodeStatus.BIDDING
                : NodeStatus.PENDING;
            nodeToDag[taskId] = dagRoot;
            dagNodes[dagRoot].push(taskNodes[i].taskId);
            emit NodeStatusChanged(taskId, nodes[taskId].status, address(0));
        }

        // Lock funds in escrow
        IMeshEscrow(meshEscrow).lockFunds{value: msg.value}(
            dagRoot, taskIds, budgets, msg.sender
        );

        emit DAGSubmitted(dagRoot, msg.sender, taskNodes.length, msg.value);
    }

    // ─────────────────────────────────────────────────────────────
    //  Status transitions
    // ─────────────────────────────────────────────────────────────

    /// @notice Called by BidEngine when a bid is awarded
    function markNodeAssigned(bytes32 taskId, address agent) external onlyBidEngine {
        TaskNode storage n = nodes[taskId];
        require(n.status == NodeStatus.BIDDING, "DAGRegistry: not in BIDDING state");
        n.assignedAgent = agent;
        n.status        = NodeStatus.ASSIGNED;
        n.assignedAt    = block.number;
        emit NodeStatusChanged(taskId, NodeStatus.ASSIGNED, agent);
    }

    /// @notice Called by BidEngine when no bid awarded (fail)
    function markNodeFailed(bytes32 taskId) external onlyBidEngine {
        TaskNode storage n = nodes[taskId];
        require(
            n.status == NodeStatus.BIDDING || n.status == NodeStatus.PENDING,
            "DAGRegistry: node not fail-ready"
        );
        n.status = NodeStatus.FAILED;
        emit NodeStatusChanged(taskId, NodeStatus.FAILED, address(0));
        IMeshEscrow(meshEscrow).refundOnTimeout(taskId);
    }

    /// @notice Called by TEEVerifierBridge when work passes verification
    function markNodeComplete(bytes32 taskId) external onlyTEE {
        TaskNode storage n = nodes[taskId];
        require(
            n.status == NodeStatus.ASSIGNED || n.status == NodeStatus.RUNNING,
            "DAGRegistry: node not active"
        );
        n.status      = NodeStatus.COMPLETE;
        n.completedAt = block.number;
        emit NodeStatusChanged(taskId, NodeStatus.COMPLETE, n.assignedAgent);

        bytes32 dagRoot = nodeToDag[taskId];
        _openReadyDependents(dagRoot);
        _maybeMarkDAGComplete(dagRoot);
    }

    /// @notice Called by TEEVerifierBridge when verification fails
    function markNodeFailedByTEE(bytes32 taskId) external onlyTEE {
        TaskNode storage n = nodes[taskId];
        require(
            n.status == NodeStatus.ASSIGNED || n.status == NodeStatus.RUNNING,
            "DAGRegistry: node not active"
        );
        n.status = NodeStatus.FAILED;
        emit NodeStatusChanged(taskId, NodeStatus.FAILED, n.assignedAgent);
        IMeshEscrow(meshEscrow).refundOnTimeout(taskId);
    }

    /// @notice Anyone can trigger a timeout refund if timeoutBlocks has passed
    function triggerTimeout(bytes32 taskId) external {
        TaskNode storage n = nodes[taskId];
        require(
            n.status == NodeStatus.ASSIGNED || n.status == NodeStatus.RUNNING,
            "DAGRegistry: node not in active state"
        );
        require(
            block.number > n.assignedAt + n.timeoutBlocks,
            "DAGRegistry: timeout not reached"
        );
        n.status = NodeStatus.FAILED;
        emit NodeStatusChanged(taskId, NodeStatus.FAILED, n.assignedAgent);
        IMeshEscrow(meshEscrow).refundOnTimeout(taskId);
    }

    // ─────────────────────────────────────────────────────────────
    //  Cycle detection — Kahn's algorithm (topological sort check)
    // ─────────────────────────────────────────────────────────────

    function _validateNoCycles(TaskNode[] calldata ns) internal pure {
        for (uint256 i = 0; i < ns.length; i++) {
            for (uint256 j = 0; j < ns[i].dependsOn.length; j++) {
                bool found = false;
                for (uint256 k = 0; k < i; k++) {
                    if (ns[k].taskId == ns[i].dependsOn[j]) {
                        found = true;
                        break;
                    }
                }
                require(found, "DAGRegistry: cycle detected or bad dependency");
            }
        }
    }

    function _openReadyDependents(bytes32 dagRoot) internal {
        bytes32[] storage ids = dagNodes[dagRoot];
        for (uint256 i = 0; i < ids.length; i++) {
            TaskNode storage n = nodes[ids[i]];
            if (n.status == NodeStatus.PENDING && dependenciesMet(ids[i])) {
                n.status = NodeStatus.BIDDING;
                emit NodeStatusChanged(ids[i], NodeStatus.BIDDING, address(0));
            }
        }
    }

    function _maybeMarkDAGComplete(bytes32 dagRoot) internal {
        DAG storage d = dags[dagRoot];
        if (d.complete) return;

        bytes32[] storage ids = dagNodes[dagRoot];
        for (uint256 i = 0; i < ids.length; i++) {
            if (nodes[ids[i]].status != NodeStatus.COMPLETE) return;
        }

        d.complete = true;
        emit DAGCompleted(dagRoot);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function getDAG(bytes32 dagRoot) external view returns (DAG memory) {
        return dags[dagRoot];
    }

    function getNode(bytes32 taskId) external view returns (TaskNode memory) {
        return nodes[taskId];
    }

    function getDAGNodes(bytes32 dagRoot) external view returns (bytes32[] memory) {
        return dagNodes[dagRoot];
    }

    function getNodeStatus(bytes32 taskId) external view returns (NodeStatus) {
        return nodes[taskId].status;
    }

    function getAssignedAgent(bytes32 taskId) external view returns (address) {
        return nodes[taskId].assignedAgent;
    }

    function dependenciesMet(bytes32 taskId) public view returns (bool) {
        bytes32[] memory deps = nodes[taskId].dependsOn;
        for (uint256 i = 0; i < deps.length; i++) {
            if (nodes[deps[i]].status != NodeStatus.COMPLETE) return false;
        }
        return true;
    }
}

contracts/TEEVerifierBridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;



interface IMeshEscrow {
function release(bytes32 taskId, address agent) external;
function getBudget(bytes32 taskId) external view returns (uint256);
}

interface IAgentRegistry {
function incrementReputation(address agent, uint8 score) external;
function slash(address agent) external;
function recordEarnings(address agent, uint256 amount) external;
}

interface IDAGRegistry {
function markNodeComplete(bytes32 taskId) external;
function markNodeFailedByTEE(bytes32 taskId) external;
function getAssignedAgent(bytes32 taskId) external view returns (address);
}

/**
 * @title TEEVerifierBridge
 * @notice Receives quality scores signed by the 0G Compute TEE node.
 *         Verifies the ECDSA signature against TEE_SIGNER_ADDRESS,
 *         then either releases escrow + boosts reputation (pass)
 *         or slashes the agent (fail).
 *
 * MAINNET DEPLOYMENT PARAMS:
 *   _escrow      : address of MeshEscrow
 *   _agentReg    : address of AgentRegistry
 *   _dagReg      : address of TaskDAGRegistry
 *   _signer      : TEE_SIGNER_ADDRESS from .env
 *                  (public address of the TEE's signing key)
 *   _mrEnclave   : TEE_MR_ENCLAVE from .env
 *                  (bytes32 image identity of the TEE program)
 *
 * DEPLOY ORDER: Last in Task Economy group.
 * After deploying, call:
 *   AgentRegistry.setTeeVerifier(thisAddress)
 *   MeshEscrow.setTeeVerifier(thisAddress)
 *   TaskDAGRegistry.setTeeVerifier(thisAddress)
 */
contract TEEVerifierBridge {

    // ─────────────────────────────────────────────────────────────
    //  Interfaces
    // ─────────────────────────────────────────────────────────────







    // ─────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────

    IMeshEscrow    public escrow;
    IAgentRegistry public agentReg;
    IDAGRegistry   public dagReg;

    address public trustedVerifierSigner; // TEE_SIGNER_ADDRESS
    bytes32 public trustedMrEnclave;      // TEE_MR_ENCLAVE
    address public owner;

    uint8 public MIN_QUALITY = 70; // minimum score to pass (0–100)
    uint256 private constant SECP256K1N_HALF =
        0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0;

    mapping(bytes32 => bool) public processed; // taskId => already verified

    // ─────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────

    event VerificationSubmitted(
        bytes32 indexed taskId,
        address indexed agent,
        bool    passed,
        uint8   score,
        uint256 payout
    );
    event SignerUpdated(address newSigner);
    event EnclaveUpdated(bytes32 newMrEnclave);
    event MinQualityUpdated(uint8 newMin);

    // ─────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        require(msg.sender == owner, "TEEVerifier: not owner");
        _;
    }

    // ─────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────

    constructor(
        address _escrow,
        address _agentReg,
        address _dagReg,
        address _signer,
        bytes32 _mrEnclave
    ) {
        require(_escrow   != address(0), "zero escrow");
        require(_agentReg != address(0), "zero agentReg");
        require(_dagReg   != address(0), "zero dagReg");
        require(_signer   != address(0), "zero signer");

        escrow                 = IMeshEscrow(_escrow);
        agentReg               = IAgentRegistry(_agentReg);
        dagReg                 = IDAGRegistry(_dagReg);
        trustedVerifierSigner  = _signer;
        trustedMrEnclave       = _mrEnclave;
        owner                  = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────
    //  Admin
    // ─────────────────────────────────────────────────────────────

    function updateSigner(address _newSigner) external onlyOwner {
        require(_newSigner != address(0), "zero signer");
        trustedVerifierSigner = _newSigner;
        emit SignerUpdated(_newSigner);
    }

    function updateMrEnclave(bytes32 _newEnclave) external onlyOwner {
        trustedMrEnclave = _newEnclave;
        emit EnclaveUpdated(_newEnclave);
    }

    function setMinQuality(uint8 _min) external onlyOwner {
        MIN_QUALITY = _min;
        emit MinQualityUpdated(_min);
    }

    // ─────────────────────────────────────────────────────────────
    //  Verification — called by backend after polling TEE result
    // ─────────────────────────────────────────────────────────────

    /**
     * @notice Submit a TEE-signed verification result.
     *
     * @param taskId        bytes32 task identifier
     * @param assignedAgent address of the agent who did the work
     * @param passed        true if score >= MIN_QUALITY
     * @param score         quality score 0–100 from TEE
     * @param teeSignature  ECDSA signature from the TEE node
     *                      — must be signed by TEE_SIGNER_ADDRESS
     *                      — message: keccak256(chainId, verifier, taskId,
     *                        assignedAgent, passed, score, mrEnclave)
     */
    function submitVerification(
        bytes32        taskId,
        address        assignedAgent,
        bool           passed,
        uint8          score,
        bytes calldata teeSignature
    ) external {
        require(!processed[taskId],           "TEEVerifier: already processed");
        require(assignedAgent != address(0),  "TEEVerifier: zero agent");
        require(score <= 100,                 "TEEVerifier: score > 100");
        require(
            dagReg.getAssignedAgent(taskId) == assignedAgent,
            "TEEVerifier: agent mismatch"
        );

        // Reconstruct signed message including mrEnclave for enclave binding
        bytes32 msgHash = keccak256(
            abi.encodePacked(
                block.chainid,
                address(this),
                taskId,
                assignedAgent,
                passed,
                score,
                trustedMrEnclave
            )
        );
        bytes32 ethHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", msgHash)
        );

        address recovered = _recover(ethHash, teeSignature);
        require(
            recovered == trustedVerifierSigner,
            "TEEVerifier: invalid TEE attestation"
        );

        processed[taskId] = true;

        if (passed && score >= MIN_QUALITY) {
            uint256 payout = escrow.getBudget(taskId);
            escrow.release(taskId, assignedAgent);
            agentReg.incrementReputation(assignedAgent, score);
            agentReg.recordEarnings(assignedAgent, payout);
            dagReg.markNodeComplete(taskId);
            emit VerificationSubmitted(taskId, assignedAgent, true, score, payout);
        } else {
            agentReg.slash(assignedAgent);
            dagReg.markNodeFailedByTEE(taskId);
            emit VerificationSubmitted(taskId, assignedAgent, false, score, 0);
        }
    }

    // ─────────────────────────────────────────────────────────────
    //  Internal — ECDSA recovery
    // ─────────────────────────────────────────────────────────────

    function _recover(bytes32 h, bytes calldata sig) internal pure returns (address) {
        require(sig.length == 65, "TEEVerifier: bad sig length");
        bytes32 r;
        bytes32 s;
        uint8   v;
        assembly {
            r := calldataload(sig.offset)
            s := calldataload(add(sig.offset, 32))
            v := byte(0, calldataload(add(sig.offset, 64)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "TEEVerifier: bad v");
        require(uint256(s) <= SECP256K1N_HALF, "TEEVerifier: bad s");
        return ecrecover(h, v, r, s);
    }

    // ─────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────

    function isProcessed(bytes32 taskId) external view returns (bool) {
        return processed[taskId];
    }
}

